public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the input parameters are valid
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    // Define the maximum size of the list to store visited nodes
    int MAX_SIZE = n * n;

    // Initialize a set to keep track of visited nodes
    HashSet<Integer> visited = new HashSet<>();

    // Use a deque as a queue for breadth-first search
    Deque<int[]> queue = new LinkedList<>();
    queue.offer(start.clone());
    visited.add(start[0]);

    // Perform breadth-first search
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int[] next = new int[]{current[0] + path[0], current[1] + path[1]};
            // Check if the next position is within the bounds of the space
            if (next[0] >= 0 && next[0] < n && next[1] >= 0 && next[1] < n
                    && !visited.contains(next[0] * n + next[1])) {
                visited.add(next[0] * n + next[1]);
                queue.offer(next.clone());
            }
        }
    }

    // If no path was found to the ending n-tersection
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    // Replace spaces with an empty string
    String upper1 = word1.replaceAll(" ", "");
    String upper2 = word2.replaceAll(" ", "");

    // Initialize the result string
    String result;

    // Check if there is a division by zero
    if (upper1.length() == 0 || upper2.length() == 0) {
        result = "appx(" + word1 + ", " + word2 + ") = undefined";
    } else {
        // Calculate the number of common letters
        int commonLetters = 0;
        for (char char1 : upper1.toCharArray()) {
            for (char char2 : upper2.toCharArray()) {
                if (char1 == char2) {
                    commonLetters++;
                    break;
                }
            }
        }

        // Calculate the total length
        int totalLength = upper1.length() + upper2.length();

        // Calculate the approximate value
        BigInteger numerator = BigInteger.valueOf(commonLetters);
        BigInteger denominator = BigInteger.valueOf(totalLength);
        BigInteger gcd = numerator.gcd(denominator);

        // Reduce the fraction
        numerator = numerator.divide(gcd);
        denominator = denominator.divide(gcd);

        result = "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }

    return result;
}

