    if ((arr.length * (arr.length + 1) / 2) % k != 0) {
        return false;
    }

    // Count the remainders of the array elements when divided by k
    int[] remainderCount = new int[k];

    for (int num : arr) {
        remainderCount[num % k]++;
    }

    // Check if the elements can be paired
    for (int i = 0; i < k; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    // If all conditions are met, return true
    return true;
}

