public boolean splitArraySameAverage(int[] nums) {
    // Exclude zero for simplicity
    if (nums == null || nums.length == 0 || nums.length == 1 || nums[0] == 0) return false;

    // Calculate the total sum of numbers
    int total = 0;
    for (int num : nums) {
        total += num;
    }

    // Ensure the total sum is divisible by the length of the array
    if (total % nums.length != 0) return false;

    // Split the sum into two equal parts
    double targetSum = total / nums.length;

    // Check all possible equidistant split points
    for (int size = (int) (total / 2); size < nums.length; size++) {
        if (hasEquidistantSum(nums, size, targetSum)) return true;
    }

    return false;
}

private boolean hasEquidistantSum(int[] nums, int size, double targetSum) {
    int leftSum = 0, rightSum = 0;
    for (int i = 0; i < size; i++) {
        leftSum += nums[i];
    }

    for (int i = size; i < nums.length; i++) {
        rightSum += nums[i];

        // Check if both left and right sums are equal to the target sum
        if (leftSum == targetSum && rightSum == targetSum) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input cost array cannot be null or empty");
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

