}

private void dfs(String str, int index, String current, int& maxUnique, boolean[] used, int[][] uniquePermutations) {
    if (index == str.length()) {
        maxUnique = Math.max(maxUnique, current.length() - str.length());
        return;
    }
    for(int i = 0; i < 26; i++) {
        char c = (char) ('a' + i);
        if (used[i] || str.charAt(index) == c) {
            continue;
        }
        int sum = 0;
        for(int j = 0 ; j < current.length(); j++) {
            sum = sum * 26 + current.charAt(j) - 'a';
        }
        sum = sum * 26 + c - 'a';
        if (sum >= 0 && sum < 26) {
            uniquePermutations[used[0]][used[1]][sum]++;
        }
        used[c - 'a'] = true;
        dfs(str, index + 1, current + c, maxUnique, used, uniquePermutations);
        used[c - 'a'] = false;
    }
}

