        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    if (n == 0) {
        return 0;
    }

    int count = 0;
    int current = 1;

    while (n > 0) {
        int digit = n % 10;
        if (digit == 1) {
            count += n + 1;
        } else if (digit > 1) {
            count += 10 * current;
        }
        n /= 10;
        current *= 10;
    }

    return count;
}

