    // Use bitwise operation to check if n is a power of 2
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    while(num >= 10) {
        num = sumOfDigits(num);
    }
    return num;
}

private static int sumOfDigits(int n) {
    int sum = 0;
    while(n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

public static int longestLine(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return 0;
        }

        int len = 0;

        int count0 = 0, count1 = 1;
        int count.drawLine0 = 0, count.drawLine1 = 0;

        for (int row = 0; row < mat.length; row++) {
            for (int col = 0; col < mat[0].length; col++) {

                if (mat[row][col] == 0) {
                    count0++;
                    count1 = 1;
                    count.drawLine0 = 0;
                    count.drawLine1 = 0;
                } else if (mat[row][col] == 1) {
                    count0 = 1;
                    count1++;
                    count.drawLine0 = Math.max(count.drawLine0, count1);
                    count.drawLine1 =Math.max(count.drawLine1, count0);

                    if (row - 1 >= 0 && mat[row - 1][col - 1] == 1) {
                        count1++;
                        count.drawLine0 = Math.max(count.drawLine0, count1);
                        count.drawLine1 = Math.max(count.drawLine1, count1 - 1);
                    }
                    if (row - 1 >= 0 && mat[row - 1][col + 1] == 1) {
                        count1++;
                        count.drawLine0 = Math.max(count.drawLine0, count1);
                        count.drawLine1 = Math.max(count.drawLine1, count1 - 1);
                    }
                }

                len = Math.max(len, count.drawLine0);
                len = Math.max(len, count.drawLine1);
            }
        }

        return len;
    }

public static String addThousandSeparator(int n) {
    if (n < 0) return " negative " + addThousandSeparator(-n);
    if (n == 0) return "0";

    StringBuilder builder = new StringBuilder();
    while (n > 0) {
        int remainder = n % 1000;
        if (remainder != 0) {
            if (builder.length() > 0) builder.append(".");
            builder.insert(0, remainder);
        }
        n /= 1000;
    }
    return builder.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }
    int n = A.length;
    int[] count = new int[n];
    Arrays.fill(count, 1);
    for (int i = 0; i < n - 1; i++) {
        if (A[i] > 0) {
            if (isPerfectSquare(A[i] * A[i + 1])) {
                int next = i + 2 < n ? count[i + 2] : 1;
                count[i + 1] = next + count[i]
            }
        }
    }
    return count[n - 1];
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    int maxArea = 0;
    int[] stack = new int[heights.length];
    int index = -1;

    for (int i = 0; i < heights.length; i++) {
        while (index != -1 && heights[stack[index]] >= heights[i]) {
            int height = heights[stack[index--]];
            int width = index == -1 ? i : i - stack[index - 1] - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++index] = i;
    }

    while (index != -1) {
        int height = heights[stack[index--]];
        int width = index == -1 ? heights.length : heights.length - stack[index - 1] - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat){
    if(mat.length==0){
        return new int[]{};
    }
    // array used for storing the result
    int[] res = new int[mat[0].length*mat.length];
    int index = 0;
    // start and end for the 2D array
    int startRow = 0;
    int endRow = mat.length-1;
    int startCol = 0;
    int endCol = mat[0].length-1;

    while(startCol<=endCol){
        int tie = indices(startRow,startCol);
        for(int i=startRow;i<=endRow;i++){
            res[tie]=mat[i][startCol];
            tie+=1;
        }
        startRow++;
    }
    tie = indices(startRow,endCol);
    for(int i=startCol;i<=endCol;i++){
        res[tie]=mat[endRow][i];
        tie+=1;
    }
    endRow--;

    while(endCol>=startCol){
        int tie = indices(startRow,endCol);
        for(int i=endRow;i>=startRow;i--){
            res[tie]=mat[i][endCol];
            tie+=1;
        }
        endCol--;
    }
   tie = indices(endRow,startCol);
    for(int i=startCol;i<=endCol;i++){
        res[tie]=mat[startRow][i];
        tie+=1;
    }
    return res;
}

int indices(int row, int col){
    if(row==col){
        return row;
    }
    if(row>col){
        return 2*col-row+1;
    }
    return 2*row+col-1;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) {
        return -1; // If n is a single digit, no smaller number can be formed.
    }

    // Convert the integer to a string to easily manipulate its digits.
    char[] digits = String.valueOf(n).toCharArray();
    int largestIndex = digits.length - 1;
    int smallestIndex = 0;

    // Find the first digit that can be swapped to form a smallernumber.
    while (largestIndex - smallestIndex > 0 && digits[largestIndex] >= digits[smallestIndex]) {
        largestIndex--;
    }

    // If no such digit is found, it means n is already the smallest permutation.
    if (largestIndex == smallestIndex) {
        return -1;
    }

    // Find the smallest digit in the remaining portion of the string that is greater than the digit found in the first step.
    for (int i = largestIndex - 1; i >= 0; i--) {
        if (digits[i] > digits[largestIndex]) {
            // Swap these two digits.
            char temp = digits[i];
            digits[i] = digits[largestIndex];
            digits[largestIndex] = temp;
            break;
        }
    }

    // Sort the remaining digits in ascending order to form the smallest number.
    Arrays.sort(digits, smallestIndex, largestIndex + 1);

    // Convert the sorted array back to an integer.
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();

    // No center symmetric number with length 0
    if (n == 0) {
        return result;
    }

    // For length 1, have a single 0
    if (n == 1) {
        result.add("0");
        return result;
    }

    // For odd length n, we need to balance the center with a symmetric pair
    if ((n % 2) != 0) {
        for (int i = 0; i <= n / 2; i++) {
            // Build the symmetric pair starting from the given midpoint
            StringBuilder symmetric = new StringBuilder Integer.toString(i);
            symmetric.reverse();

            // Construct the center symmetric number
            String centerSymmetric = symmetric.toString().substring(0, n / 2);
            String resultString = Integer.toString(i) + centerSymmetric + symmetric.toString().replaceFirst("-", "");

            result.add(resultString);
        }
    } else {
        // For even length n, the center symmetric number is the same as its mirror image
        for (int i = 0; i <= n / 2; i++) {
            // Construct the center symmetric number as its mirror image
            String resultString = Integer.toString(i) + buildMirror(i, n / 2);

            result.add(resultString);
        }
    }

    return result;
}

private static String buildMirror(int number, int half) {
    int reversed = 0;
    while (number > 0) {
        reversed = reversed * 10 + number % 10;
        number /= 10;
    }
    return reversed == 0 ? "" : "-" + reversed;
}

public static boolean isBoomerang(int[][] points) {
    int N = points.length;
    if (N != 3) {
        throw new IllegalArgumentException("Input must contain exactly three points");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the points form a boomerang
    // A boomerang is a set of three non-collinear points
    // - Condition 1: The product of changes in x coordinates is not equal to the product of changes in y coordinates
    // - Condition 2: The changes in x coordinates are not both zero (to avoid division by zero)
    return ((y2 - y1) * (x3 - x1) != (x2 - x1) * (y3 - y1)) && (x1 != x2 && x2 != x3 && x1 != x3);
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int multiplier2 = 0;
    int multiplier3 = 0;
    int multiplier5 = 0;

    for (int i = 1; i < n; i++) {
        int next = Math.min(uglyNumbers[multiplier2] * 2, Math.min(uglyNumbers[multiplier3] * 3, uglyNumbers[multiplier5] * 5));
        uglyNumbers[i] = next;

        if (next == uglyNumbers[multiplier2] * 2) {
            multiplier2++;
        }
        if (next == uglyNumbers[multiplier3] * 3) {
            multiplier3++;
        }
        if (next == uglyNumbers[multiplier5] * 5) {
            multiplier5++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int longest = 0;
    char prevChar = s.charAt(0);
    int currentCount = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == prevChar) {
            currentCount++;
        } else {
            longest = Math.max(longest, currentCount);
            prevChar = s.charAt(i);
            currentCount = 1;
        }
    }
    longest = Math.max(longest, currentCount); // Handle the last substring

    return longest;
}

