public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0; // No perfect square sum can be formed for 0 or negative numbers
    }
    if (n <= 3) {
        return n; // Smallest perfect square sums are 0, 1, 4, and 9
    }
    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1); // Initialize dp array

    dp[0] = 0; // Base case: 0 perfect squares sum up to 0
    dp[1] = 1;  // Minimum 1 perfect square sum is 1 (1^2)
    dp[4] = 1;  // Minimum 1 perfect square sum is 1 (2^2)
    dp[9] = 1;  // Minimum 1 perfect square sum is 1 (3^2)

    for (int i = 5; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], 1 + dp[i - j * j]);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        if (word.isEmpty()) {
            result.append(" ");
            continue;
        }
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }

    return result.toString().trim();
}
